package com.dropnest.nazifa;
import android.app.Activity;import android.os.Bundle;import android.content.Intent;import android.net.Uri;import android.webkit.ValueCallback;import android.webkit.WebChromeClient;import android.webkit.WebSettings;import android.webkit.WebView;import android.webkit.WebViewClient;
public class MainActivity extends Activity {private static final int FILE_CHOOSER=1001;private WebView webView;private ValueCallback<Uri[]> fileCallback;@Override protected void onCreate(Bundle b){super.onCreate(b);webView=new WebView(this);setContentView(webView);WebSettings s=webView.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(true);webView.setWebViewClient(new WebViewClient());webView.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){if(fileCallback!=null)fileCallback.onReceiveValue(null);fileCallback=cb;Intent i=new Intent(Intent.ACTION_GET_CONTENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/*","application/pdf","text/plain"});startActivityForResult(Intent.createChooser(i,"Choose a photo or file"),FILE_CHOOSER);return true;}});webView.loadUrl("file:///android_asset/index.html");}@Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==FILE_CHOOSER&&fileCallback!=null){Uri[] values=null;if(result==RESULT_OK&&data!=null&&data.getData()!=null)values=new Uri[]{data.getData()};fileCallback.onReceiveValue(values);fileCallback=null;}}@Override public void onBackPressed(){if(webView!=null&&webView.canGoBack())webView.goBack();else super.onBackPressed();}}